window.vassilich_elements={lib:{},assets:[],shapes:{},setup:function(h){
const n=h.MovieClip,e=h.Container,a=h.Sprite,z=h.Text,A=h.Graphics;

// ── Утилиты ────────────────────────────────────────────────────────
const mkBtn=(label,w,ht,fill,border,textFill)=>{
  fill=fill||0x1a3a10;border=border||0x3a7a20;textFill=textFill||'#b0e060';
  const bg=new A();bg.beginFill(fill,1);bg.lineStyle(1,border);bg.drawRoundedRect(0,0,w,ht,4);bg.endFill();
  const t=new z(label,{fontFamily:'Southbank LT',fontSize:12,fontWeight:'bold',fill:textFill,align:'center'});
  t.anchor.set(0.5,0.5);t.x=w/2;t.y=ht/2;
  const c=new e();c.addChild(bg,t);c.interactive=true;c.buttonMode=true;
  c.on('mouseover',()=>bg.tint=0xddeecc);c.on('mouseout',()=>bg.tint=0xffffff);
  c._bg=bg;return c;
};

// ── Вкладка ────────────────────────────────────────────────────────
vassilich_elements.lib.Vass_tab=class extends e{
  constructor(label,w){
    super();this._w=w;
    this.bg=new A();this._draw(false);
    const t=new z(label,{fontFamily:'Southbank LT',fontSize:13,fontWeight:'bold',fill:'#b0c880',align:'center'});
    t.anchor.set(0.5,0.5);t.x=w/2;t.y=20;this[t.name='label_txt']=t;
    this.addChild(this.bg,t);this.interactive=true;this.buttonMode=true;
    this.on('mouseover',()=>{if(!this._active)this._draw('hover');});
    this.on('mouseout',()=>{if(!this._active)this._draw(false);});
  }
  _draw(s){
    this.bg.clear();
    if(s==='active'){this.bg.beginFill(0x162e10,1);this.bg.lineStyle(1,0x4a8a30);}
    else if(s==='hover'){this.bg.beginFill(0x0e1e0a,1);this.bg.lineStyle(1,0x2a5a20,0.7);}
    else{this.bg.beginFill(0x080e06,0.9);this.bg.lineStyle(1,0x182a10,0.6);}
    this.bg.drawRoundedRect(0,0,this._w,38,4);this.bg.endFill();
  }
  setActive(v){this._active=v;this._draw(v?'active':false);}
};

// ── Карточка товара в магазине ─────────────────────────────────────
vassilich_elements.lib.Shop_item=class extends e{
  constructor(){
    super();
    const bg=new A();bg.beginFill(0x0a1808,0.92);bg.lineStyle(1,0x1e3c14,0.8);bg.drawRoundedRect(0,0,370,130,5);bg.endFill();
    this.addChild(bg);
    // Иконка-плейсхолдер
    const ib=new A();ib.beginFill(0x101e0c,1);ib.lineStyle(1,0x2a4a1e);ib.drawRoundedRect(8,8,64,64,4);ib.endFill();
    const ii=new z('?',{fontFamily:'Arial',fontSize:28,fill:'#3a6a2a'});ii.anchor.set(0.5,0.5);ii.x=40;ii.y=40;
    this[ii.name='icon_txt']=ii;this.addChild(ib,ii);
    // Название
    const nt=new z('',{fontFamily:'Southbank LT',fontSize:14,fontWeight:'bold',fill:'#d0e880'});nt.x=82;nt.y=8;
    this[nt.name='name_txt']=nt;
    // Описание
    const dt=new z('',{fontFamily:'Arial',fontSize:11,fill:'#7a9a5a',wordWrap:true,wordWrapWidth:278});dt.x=82;dt.y=30;
    this[dt.name='desc_txt']=dt;
    // Цена
    const pt=new z('',{fontFamily:'Southbank LT',fontSize:13,fontWeight:'bold',fill:'#c8a840'});pt.x=82;pt.y=60;
    this[pt.name='price_txt']=pt;
    // Кол-во в наличии
    const st=new z('',{fontFamily:'Arial',fontSize:11,fill:'#6a8a4a'});st.x=82;st.y=80;
    this[st.name='stock_txt']=st;
    // Кнопка купить
    const bb=mkBtn('КУПИТЬ',100,32);bb.x=258;bb.y=90;
    this[bb.name='butt_buy']=bb;
    this.addChild(nt,dt,pt,st,bb);
  }
};

// ── Слот рюкзака ───────────────────────────────────────────────────
vassilich_elements.lib.Bp_slot=class extends e{
  constructor(){
    super();
    const bg=new A();bg.beginFill(0x0a1808,0.85);bg.lineStyle(1,0x1a3010,0.7);bg.drawRoundedRect(0,0,130,130,5);bg.endFill();
    this.addChild(bg);
    const ii=new z('',{fontFamily:'Arial',fontSize:30,fill:'#2a4a1a',align:'center'});ii.anchor.set(0.5);ii.x=65;ii.y=50;
    this[ii.name='icon_txt']=ii;
    const nt=new z('',{fontFamily:'Southbank LT',fontSize:11,fill:'#8ab060',align:'center',wordWrap:true,wordWrapWidth:120});
    nt.anchor.set(0.5,1);nt.x=65;nt.y=122;this[nt.name='name_txt']=nt;
    const ct=new z('',{fontFamily:'Southbank LT',fontSize:10,fill:'#c8a030'});ct.x=4;ct.y=4;
    this[ct.name='count_txt']=ct;
    const ub=mkBtn('ИСПОЛЬ.',118,28,0x0e2a08,0x2a6018,'#80c040');ub.x=6;ub.y=96;ub.visible=false;
    this[ub.name='butt_use']=ub;
    this.addChild(ii,nt,ct,ub);
    this.interactive=true;this.buttonMode=true;
  }
  setEmpty(){
    this.icon_txt.text='';this.name_txt.text='';this.count_txt.text='';this.butt_use.visible=false;
  }
};

// ── Потеряшки (лут-ящик) ──────────────────────────────────────────
vassilich_elements.lib.Loot_section=class extends e{
  constructor(){
    super();
    // Фон секции
    const bg=new A();bg.beginFill(0x080e06,0.5);bg.drawRect(0,0,1180,420);bg.endFill();this.addChild(bg);
    // Иконка ящика
    const chest=new A();
    chest.beginFill(0x1a2e0a,1);chest.lineStyle(2,0x4a7a20,0.9);chest.drawRoundedRect(0,0,180,160,8);chest.endFill();
    chest.beginFill(0x2a4a14,1);chest.lineStyle(1,0x5a9a30);chest.drawRect(0,70,180,8);chest.endFill();
    const lock=new A();lock.beginFill(0x8a7020,1);lock.drawCircle(90,74,18);lock.endFill();
    const lock2=new A();lock2.beginFill(0x2a2000,1);lock2.drawCircle(90,74,10);lock2.endFill();
    const cg=new e();cg.addChild(chest,lock,lock2);cg.x=500;cg.y=30;this[cg.name='chest_mc']=cg;this.addChild(cg);
    // Подпись
    const lt=new z('ПОТЕРЯШКИ',{fontFamily:'Southbank LT',fontSize:20,fontWeight:'bold',fill:'#c8a030',letterSpacing:4,align:'center',dropShadow:true,dropShadowDistance:2,dropShadowColor:'#000'});
    lt.anchor.set(0.5);lt.x=590;lt.y=210;this.addChild(lt);
    const desc=new z('Случайные ценности, найденные в Зоне.\nОткройте ящик и проверьте удачу!',{fontFamily:'Arial',fontSize:13,fill:'#7a9a5a',align:'center',wordWrap:true,wordWrapWidth:600,lineHeight:20});
    desc.anchor.set(0.5);desc.x=590;desc.y=248;this.addChild(desc);
    // Кнопка открыть
    const ob=mkBtn('ОТКРЫТЬ  (5 папирос)',240,46,0x2a1a00,0x7a5010,'#f0c040');ob.x=470;ob.y=290;
    this[ob.name='butt_open']=ob;this.addChild(ob);
    // Последние выигрыши
    const last_lbl=new z('Последние находки:',{fontFamily:'Southbank LT',fontSize:11,fill:'#4a6a3a'});last_lbl.x=10;last_lbl.y=360;this.addChild(last_lbl);
    const lt2=new z('',{fontFamily:'Arial',fontSize:11,fill:'#9aaa6a',wordWrap:true,wordWrapWidth:1160});lt2.x=10;lt2.y=378;
    this[lt2.name='last_txt']=lt2;this.addChild(lt2);
  }
};

// ── Главное окно Василича ─────────────────────────────────────────
vassilich_elements.lib.Vassilich_win=class extends e{
  constructor(){
    super();
    // Окно
    const wb=new A();wb.beginFill(0x060c04,0.97);wb.lineStyle(2,0x2a5a18,0.9);wb.drawRoundedRect(0,0,1200,524,6);wb.endFill();
    this.addChild(wb);
    // Хедер
    const hb=new A();hb.beginFill(0x0a1c06,1);hb.drawRect(2,2,1196,42);hb.endFill();
    const hl=new A();hl.lineStyle(1,0x2a5a18,0.5);hl.moveTo(2,45);hl.lineTo(1198,45);
    this.addChild(hb,hl);
    const ttl=new z('СИДОРОВИЧ',{fontFamily:'Southbank LT',fontSize:18,fontWeight:'bold',fill:'#c8d840',letterSpacing:5,dropShadow:true,dropShadowDistance:2,dropShadowColor:'#000'});
    ttl.x=20;ttl.y=12;this.addChild(ttl);
    // Реплика Василича
    const speech=new z('"Что надо, сталкер? Только без резких движений."',{fontFamily:'Arial',fontSize:11,fill:'#6a8a4a',fontStyle:'italic'});
    speech.x=200;speech.y=15;this.addChild(speech);
    // Закрыть
    const cbg=new A();cbg.beginFill(0x3a1010,1);cbg.lineStyle(1,0x882222);cbg.drawRoundedRect(0,0,30,30,4);cbg.endFill();
    const ctx=new z('×',{fontFamily:'Arial',fontSize:22,fill:'#cc4444'});ctx.anchor.set(0.5,0.5);ctx.x=15;ctx.y=15;
    const cl=new e();cl.addChild(cbg,ctx);cl.x=1162;cl.y=7;
    cl.interactive=true;cl.buttonMode=true;
    cl.on('mouseover',()=>cbg.tint=0xddaaaa);cl.on('mouseout',()=>cbg.tint=0xffffff);
    this[cl.name='butt_close']=cl;this.addChild(cl);
    // Вкладки (3)
    const tab_labels=['Магазин','Потеряшки','Рюкзак'],tw=388,tgap=8;
    const tabs=new e();tabs.x=10;tabs.y=48;
    for(let i=0;i<3;i++){const tb=new vassilich_elements.lib.Vass_tab(tab_labels[i],tw);tb.x=i*(tw+tgap);tabs['tab_'+i]=tb;tabs.addChild(tb);}
    this[tabs.name='tabs']=tabs;this.addChild(tabs);
    // Разделитель
    const tdiv=new A();tdiv.lineStyle(1,0x2a4a18,0.5);tdiv.moveTo(10,89);tdiv.lineTo(1190,89);this.addChild(tdiv);

    // ── Секция: Магазин ────────────────────────────────────────────
    const shop=new e();shop.x=10;shop.y=96;
    for(let i=0;i<6;i++){
      const si=new vassilich_elements.lib.Shop_item();
      si.x=(i%3)*(370+8);si.y=Math.floor(i/3)*(130+8);
      shop['item_'+i]=si;shop.addChild(si);
    }
    this[shop.name='shop_section']=shop;this.addChild(shop);

    // ── Секция: Потеряшки ──────────────────────────────────────────
    const loot=new vassilich_elements.lib.Loot_section();loot.x=10;loot.y=92;loot.visible=false;
    this[loot.name='loot_section']=loot;this.addChild(loot);

    // ── Секция: Рюкзак ────────────────────────────────────────────
    const bp=new e();bp.x=10;bp.y=96;bp.visible=false;
    for(let i=0;i<9;i++){
      const sl=new vassilich_elements.lib.Bp_slot();
      sl.x=(i%9)*(130+6);sl.y=0;
      // 2 ряда: 0-8 первый, 9-17 второй — но для начала один ряд 9 слотов
      bp['slot_'+i]=sl;bp.addChild(sl);
    }
    // Второй ряд
    for(let i=9;i<18;i++){
      const sl=new vassilich_elements.lib.Bp_slot();
      sl.x=((i-9)%9)*(130+6);sl.y=138;
      bp['slot_'+i]=sl;bp.addChild(sl);
    }
    this[bp.name='bp_section']=bp;this.addChild(bp);
  }
};

// ── Root MovieClip ─────────────────────────────────────────────────
vassilich_elements.lib.vassilich_elements=class extends n{
  constructor(){
    super({duration:1,framerate:30});
    const b=new vassilich_elements.lib.Vassilich_win();
    this[b.name='vassilich_win']=b;this.addChild(b);
  }
};
vassilich_elements.stage=vassilich_elements.lib.vassilich_elements}};
